#!/usr/bin/env Rscript
source(file.path(dirname(normalizePath(sub("^--file=", "", commandArgs(FALSE)[grep("^--file=", commandArgs(FALSE))]))), "dv_shared.R"))
dv_require(c("limma","statmod","digest"));marker<-dv_assert_unlock();hash<-dv_assert_candidate_hash();stage<-"D08_validation";outdir<-dv_stage_dir(stage)
meta<-dv_assignment("Validation");ef<-file.path(outdir,"D08_validation_locked_raw_expression.csv.gz");expr<-dv_read_expression(ef,meta$UniqueSampleID,TRUE);lockf<-file.path(dv_stage_dir("D03_candidate_lock"),"D03_locked_candidates.csv");lock<-dv_read_csv(lockf,c("PG.ProteinGroups","log2FC"));if(!identical(rownames(expr),lock$PG.ProteinGroups))dv_stop("D08 universe is not exactly D03 lock")
d<-dv_design(meta);r<-dv_fit(expr,d,dv_primary_contrast(d),family_n=nrow(lock));names(r)[names(r)=="BH_FDR"]<-"Candidate_family_BH_FDR";r$Discovery_log2FC<-lock$log2FC[match(r$PG.ProteinGroups,lock$PG.ProteinGroups)];r$Direction_concordant<-sign(r$log2FC)==sign(r$Discovery_log2FC);r$Nominal_replication<-r$Direction_concordant&r$P_value<.05;r$FDR_supported_replication<-r$Direction_concordant&r$Candidate_family_BH_FDR<.05;r$Effect_difference_signed<-r$log2FC-r$Discovery_log2FC;r$Effect_difference_absolute<-abs(r$Effect_difference_signed)
nlock<-nrow(lock);nest<-sum(r$Model_status=="ESTIMABLE"&is.finite(r$log2FC));summary<-data.frame(Metric=c("N_locked","N_estimable","N_direction_concordant","N_nominal_replication","N_FDR_supported","Direction_rate_all","Nominal_rate_all","FDR_rate_all","Direction_rate_estimable","Nominal_rate_estimable","FDR_rate_estimable"),Value=c(nlock,nest,sum(r$Direction_concordant,na.rm=TRUE),sum(r$Nominal_replication,na.rm=TRUE),sum(r$FDR_supported_replication,na.rm=TRUE),sum(r$Direction_concordant,na.rm=TRUE)/nlock,sum(r$Nominal_replication,na.rm=TRUE)/nlock,sum(r$FDR_supported_replication,na.rm=TRUE)/nlock,sum(r$Direction_concordant,na.rm=TRUE)/nest,sum(r$Nominal_replication,na.rm=TRUE)/nest,sum(r$FDR_supported_replication,na.rm=TRUE)/nest))
envres<-list();for(env in DV_ENV){keep<-meta$Environment==env;m<-meta[keep,,drop=FALSE];m$dose<-factor(m$TREAT1_clean,levels=DV_DOSE);dd<-model.matrix(~0+dose,m);colnames(dd)<-make.names(colnames(dd));if(qr(dd)$rank<ncol(dd)){z<-data.frame(PG.ProteinGroups=rownames(expr),Environment=env,Model_status="NON_ESTIMABLE")}else{z<-dv_fit(expr[,keep,drop=FALSE],dd,dv_primary_contrast(dd),family_n=nlock);z$Environment<-env};envres[[env]]<-z}
paths<-file.path(outdir,c("D08_validation_results.csv","D08_replication_summary.csv","D08_environment_specific_validation.csv","D08_manifest.csv"));dv_no_overwrite(paths);dv_write(dv_add_annotation(r),paths[1]);dv_write(summary,paths[2]);dv_write(dv_add_annotation(do.call(rbind,envres)),paths[3]);dv_write(dv_manifest(stage,c(ef,lockf,DV_ASSIGNMENT,marker),paths[1:3],list(candidate_hash=hash,universe="D03 locked candidates only",denominators="N_locked primary; N_estimable companion")),paths[4])
